/**
 * `pnpm --filter @openverify/api analytics:benchmark --seed | --measure | --teardown` (C163.7,
 * review F22): the non-gated analytics benchmark on its own container of the pinned Postgres image
 * (`pgvector/pgvector:pg17`, never the developer's compose database or the e2e stack), at 1 M
 * inquiries and 12 M check rows. Each phase is its own call and fits one:
 * - `--seed` starts the container (or finds it), migrates it and loads the synthetic population,
 *   generated by SQL from a fixed rule (no real person, no value), in batches it records, so a call
 *   that runs out of time is continued by the next one where it stopped;
 * - `--measure` times the rollup build (the first pass over a year of days), a 5-minute refresh of
 *   two dirty days, the outcome refresh of the open days after midnight, and the six reads over 30,
 *   90 and 400 days, each timing printed with the load average beside it;
 * - `--teardown` removes the container.
 * The result goes into `docs/PROGRESS.md`. Built by `api-analytics` (Workflow 9B).
 */
import { execFileSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { loadavg } from 'node:os';
import { performance } from 'node:perf_hooks';
import { pathToFileURL } from 'node:url';
import type { AnalyticsReport } from '@openverify/core';
import {
  createDatabase,
  createEnvironment,
  createInquiry,
  createInquiryTemplate,
  createKeyring,
  createOrganization,
  runMigrations,
  sealJson,
  setDefaultKeyring,
  type Database,
  type Db,
} from '@openverify/db';
import { sql, type SQL } from 'drizzle-orm';
import { Pool } from 'pg';
import { runAnalyticsRollup } from '../src/jobs/analytics/rollup.js';
import { ensureDefaultAccountType } from '../src/services/accounts.js';
import { readAnalyticsAnswer } from '../src/services/analytics/service.js';

/** The two measured phases, each its own call. */
export const ANALYTICS_BENCHMARK_PHASES = Object.freeze(['--seed', '--measure'] as const);
export type AnalyticsBenchmarkPhase = (typeof ANALYTICS_BENCHMARK_PHASES)[number];
/** Removes the benchmark's container. */
export const ANALYTICS_BENCHMARK_TEARDOWN = '--teardown';

/** The population (C163.7): 1 M inquiries over a year, two attempts each, six checks each. */
export const ANALYTICS_BENCHMARK_SIZE = Object.freeze({
  inquiries: 1_000_000,
  days: 365,
  attemptsPerInquiry: 2,
  checksPerAttempt: 6,
  stepsPerInquiry: 3,
  batch: 50_000,
  /** 10A's carried item (Workflow 11D): one case for every 20 inquiries (5%). */
  inquiriesPerCase: 20,
});

const BENCHMARK_CASE_TEMPLATE = 'ctmpl_0000000000000000000000BNCH';
const BENCHMARK_CASE_TEMPLATE_VERSION = 'ctmplv_0000000000000000000000BNCH';
/** The template's statuses: the three categories the seeded cases cover. */
const BENCHMARK_CASE_STATUSES = [
  { key: 'open', label: 'Open', category: 'initial' },
  { key: 'pending', label: 'Pending', category: 'intermediate' },
  { key: 'approved', label: 'Approved', category: 'end' },
  { key: 'declined', label: 'Declined', category: 'end' },
];

/** The cases of the inquiries `from` to `to` of a batch (10A's carried item; Workflow 11D). */
export function benchmarkCasesStatement(input: {
  environmentId: string;
  caseTemplateId: string;
  caseTemplateVersionId: string;
  from: number;
  to: number;
  /**
   * The fields every case of the batch carries: an empty object sealed once, for the batch's first
   * case. The table requires sealed fields until a redaction (`cases_fields_until_redacted`); the
   * rollups never open them, and a scratch benchmark database seals nothing per row.
   */
  fieldsSealed: string;
}): SQL {
  const per = ANALYTICS_BENCHMARK_SIZE.inquiriesPerCase;
  const day = sql.raw(
    `(timestamptz '${FIRST_DAY} 08:00:00+00' + (g % ${String(ANALYTICS_BENCHMARK_SIZE.days)}) * interval '1 day' + (g % 600) * interval '1 minute')`,
  );
  // The g-th case of the batch (every 20th inquiry's number): open, pending or decided in turn,
  // the decided ones resolved two days later.
  return sql`insert into cases (id, environment_id, case_template_id, case_template_version_id,
      name, status, status_category, creator_type, creator_id, resolver_type, resolver_id,
      resolved_at, fields, created_at, updated_at)
    select 'case_' || upper(lpad(to_hex(g), 26, '0')), ${input.environmentId},
      ${input.caseTemplateId}, ${input.caseTemplateVersionId}, 'BENCH-' || g,
      case (g / ${per}) % 3 when 0 then 'open' when 1 then 'pending'
        else case when (g / ${per}) % 2 = 0 then 'approved' else 'declined' end end,
      case (g / ${per}) % 3 when 0 then 'initial' when 1 then 'intermediate' else 'end' end,
      'api-key', 'key_0000000000000000000000BNCH',
      case when (g / ${per}) % 3 = 2 then 'api-key' end,
      case when (g / ${per}) % 3 = 2 then 'key_0000000000000000000000BNCH' end,
      case when (g / ${per}) % 3 = 2 then ${day} + interval '2 days' end,
      ${input.fieldsSealed}, ${day}, ${day}
    from generate_series(${input.from}::int, ${input.to}::int) g
    where g % ${per} = 0
    on conflict do nothing`;
}

const CONTAINER = 'openverify-analytics-benchmark';
const IMAGE =
  'pgvector/pgvector:pg17@sha256:cf134a767f474095eeba57e0117be8e568e011a63f33fbf252f14c9b760f8e6f';
/** A placeholder: the container listens on loopback only and holds synthetic rows. */
const PASSWORD = 'change-me-analytics-benchmark';
const ZONE = 'Europe/Paris';
/** The benchmark's "now": the day after the population's last day. */
const NOW = new Date('2026-11-01T10:00:00Z');
const FIRST_DAY = '2025-11-01';

/** The `updated_at` the 5-minute refresh step gives the 48 hours of rows it touches. */
export const ANALYTICS_BENCHMARK_TOUCHED_AT = new Date(NOW.getTime() + 60_000);

/**
 * R008 (Workflow 10A): the sources the 5-minute refresh finds dirty days in, as `dirtyDays`
 * (`services/analytics/refresh.ts`) reads them, so the step times every branch of its union.
 */
export const ANALYTICS_BENCHMARK_TOUCHED_TABLES = Object.freeze([
  'inquiries',
  'verifications',
  'verification_checks',
  'cases',
] as const);

/**
 * The 5-minute refresh step's writes: the rows of every source `dirtyDays` reads created in the
 * 48 hours (the seed gives a verification and its checks their inquiry's `created_at`), touched at
 * {@link ANALYTICS_BENCHMARK_TOUCHED_AT}, so the next pass finds them dirty through each branch.
 * The tables' trigger (`openverify_set_updated_at`) keeps a value an update sets only when it
 * differs from the stored one, and writes the wall clock otherwise; a repeated `--measure` on one
 * seed would write the same value again and so leave the rows outside the benchmark's clock. The
 * rows are therefore moved to the day before the window first, then to the touched time, which
 * always differs.
 */
export async function touchRefreshWindow(db: Db, environmentId: string): Promise<void> {
  const window = sql`environment_id = ${environmentId}
      and created_at >= timestamptz '2026-10-29 23:00:00+00' and created_at < timestamptz '2026-10-31 23:00:00+00'`;
  for (const table of ANALYTICS_BENCHMARK_TOUCHED_TABLES) {
    await db.execute(
      sql`update ${sql.identifier(table)} set updated_at = timestamptz '2026-10-28 00:00:00+00' where ${window}`,
    );
    await db.execute(
      sql`update ${sql.identifier(table)} set updated_at = ${ANALYTICS_BENCHMARK_TOUCHED_AT.toISOString()}::timestamptz where ${window}`,
    );
  }
}

/** Each call stops starting batches after this long, so it fits one 10-minute call. */
const SEED_BUDGET_MS = 420_000;

/** The phase `argv` names: exactly one of `--seed`, `--measure` and `--teardown`. */
export function parseAnalyticsBenchmarkArgs(
  argv: readonly string[],
): AnalyticsBenchmarkPhase | typeof ANALYTICS_BENCHMARK_TEARDOWN {
  const [phase, ...rest] = argv;
  if (
    rest.length > 0 ||
    phase === undefined ||
    ![...ANALYTICS_BENCHMARK_PHASES, ANALYTICS_BENCHMARK_TEARDOWN].includes(phase)
  ) {
    throw new Error('usage: analytics:benchmark --seed, --measure or --teardown (one per call)');
  }
  return phase as AnalyticsBenchmarkPhase | typeof ANALYTICS_BENCHMARK_TEARDOWN;
}

const docker = (...args: string[]) =>
  execFileSync('docker', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();

/** The container's loopback port, starting it when it does not exist. */
function startContainer(): number {
  const running = docker('ps', '-a', '--filter', `name=^${CONTAINER}$`, '--format', '{{.Names}}');
  if (running !== CONTAINER) {
    docker(
      'run',
      '-d',
      '--name',
      CONTAINER,
      '-e',
      `POSTGRES_PASSWORD=${PASSWORD}`,
      '-p',
      '127.0.0.1::5432',
      IMAGE,
    );
  } else {
    docker('start', CONTAINER);
  }
  const port = Number(docker('port', CONTAINER, '5432/tcp').split('\n')[0]?.split(':').pop());
  if (!Number.isInteger(port) || port <= 0) {
    throw new Error('the benchmark container has no loopback port');
  }
  return port;
}

async function connect(): Promise<{ pool: Pool; db: Database }> {
  const port = startContainer();
  const url = `postgres://postgres:${PASSWORD}@127.0.0.1:${String(port)}/postgres`;
  for (let attempt = 0; attempt < 60; attempt += 1) {
    const pool = new Pool({ connectionString: url, max: 4 });
    try {
      await pool.query('select 1');
      return { pool, db: createDatabase(pool) };
    } catch {
      await pool.end();
      await new Promise((resolve) => setTimeout(resolve, 1_000));
    }
  }
  throw new Error('the benchmark container did not accept connections');
}

const load = () =>
  loadavg()
    .map((value) => value.toFixed(2))
    .join(' ');

function report(step: string, startedAt: number, extra: Record<string, unknown> = {}) {
  const ms = Math.round(performance.now() - startedAt);
  process.stdout.write(`${JSON.stringify({ step, ms, loadavg: load(), ...extra })}\n`);
}

async function rows<Row extends Record<string, unknown>>(
  db: Database,
  query: ReturnType<typeof sql>,
) {
  return (await db.execute<Row>(query)).rows;
}

/** The benchmark's tenant, created once; `null` before the first seed. */
async function tenantOf(db: Database) {
  const [row] = await rows<{
    environment_id: string;
    template_id: string;
    version_id: string;
    seed_id: string;
  }>(
    db,
    sql`select environment_id, template_id, version_id, seed_id from benchmark_tenant limit 1`,
  ).catch(() => []);
  return row ?? null;
}

async function seed(db: Database): Promise<void> {
  const started = performance.now();
  setDefaultKeyring(createKeyring(randomBytes(32)));
  await runMigrations(db);
  await db.execute(sql`create table if not exists benchmark_tenant (environment_id text,
    template_id text, version_id text, seed_id text)`);
  await db.execute(sql`create table if not exists benchmark_batches (batch integer primary key)`);
  let tenant = await tenantOf(db);
  if (tenant === null) {
    const organization = await createOrganization(db, {
      id: 'org_0000000000000000000000BNCH',
      name: 'Synthetic benchmark',
    });
    const environment = await createEnvironment(db, {
      id: 'env_0000000000000000000000BNCH',
      organizationId: organization.id,
      kind: 'sandbox',
    });
    await ensureDefaultAccountType(db, environment.id);
    const template = await createInquiryTemplate(db, environment.id, {
      id: 'itmpl_0000000000000000000000BNCH',
      name: 'Synthetic benchmark',
      version: { id: 'itmplv_0000000000000000000000BNCH', flow: {}, verificationConfig: {} },
    });
    const inquiry = await createInquiry(db, environment.id, {
      id: 'inq_0000000000000000000000BNCH',
      inquiryTemplateId: template.id,
      inquiryTemplateVersionId: template.latestVersion.id,
      referenceId: 'synthetic-benchmark',
      fields: {},
    });
    await db.execute(sql`update environments set settings = settings
      || ${JSON.stringify({ 'analytics-time-zone': ZONE })}::jsonb where id = ${environment.id}`);
    await db.execute(sql`insert into benchmark_tenant values (${environment.id}, ${template.id},
      ${template.latestVersion.id}, ${inquiry.id})`);
    tenant = await tenantOf(db);
  }
  if (tenant === null) {
    throw new Error('the benchmark tenant was not written');
  }
  // 10A's carried item (Workflow 11D): the case template the seeded cases are made from.
  await db.execute(sql`insert into case_templates (id, environment_id, name, key)
    values (${BENCHMARK_CASE_TEMPLATE}, ${tenant.environment_id}, 'Synthetic benchmark', 'BENCH')
    on conflict do nothing`);
  await db.execute(sql`insert into case_template_versions (id, environment_id, case_template_id,
      version, status, statuses, published_at)
    values (${BENCHMARK_CASE_TEMPLATE_VERSION}, ${tenant.environment_id}, ${BENCHMARK_CASE_TEMPLATE}, 1,
      'published', ${JSON.stringify(BENCHMARK_CASE_STATUSES)}::jsonb, now())
    on conflict do nothing`);
  const fieldsSealed = sealJson('cases.fields', 'case_0000000000000000000000BNCH', {});
  const { inquiries, batch, days } = ANALYTICS_BENCHMARK_SIZE;
  const done = new Set(
    (await rows<{ batch: number }>(db, sql`select batch from benchmark_batches`)).map(
      (row) => row.batch,
    ),
  );
  for (let index = 0; index < inquiries / batch; index += 1) {
    if (done.has(index)) {
      continue;
    }
    if (performance.now() - started > SEED_BUDGET_MS) {
      report('seed-stopped-for-time', started, {
        batchesDone: done.size,
        batches: inquiries / batch,
      });
      return;
    }
    const batchStarted = performance.now();
    await db.transaction(async (tx) => {
      const from = index * batch + 1;
      const to = (index + 1) * batch;
      const id = (prefix: string) => sql.raw(`'${prefix}_' || upper(lpad(to_hex(g), 26, '0'))`);
      const day = sql.raw(
        `(timestamptz '${FIRST_DAY} 08:00:00+00' + (g % ${String(days)}) * interval '1 day' + (g % 600) * interval '1 minute')`,
      );
      // Inquiries: 70% completed, 10% failed, 10% expired, 10% pending, two in three on the web.
      await tx.execute(sql`insert into inquiries (id, environment_id, inquiry_template_id,
          inquiry_template_version_id, account_id, fields, tags, status, started_at, completed_at,
          failed_at, expired_at, first_platform, first_device_kind, flow_outcome, created_at, updated_at)
        select ${id('inq')}, s.environment_id, s.inquiry_template_id, s.inquiry_template_version_id,
          s.account_id, s.fields, case when g % 7 = 0 then '{synthetic}'::text[] else '{}' end,
          (case g % 10 when 7 then 'failed' when 8 then 'expired' when 9 then 'pending'
            else 'completed' end)::inquiry_status,
          ${day} + interval '10 seconds',
          case when g % 10 < 7 then ${day} + (g % 3600) * interval '1 second' end,
          case when g % 10 = 7 then ${day} + interval '20 minutes' end,
          case when g % 10 = 8 then ${day} + interval '1 day' end,
          case when g % 3 = 2 then 'android' else 'web' end,
          case when g % 3 = 2 then 'native' when g % 3 = 1 then 'mobile-web' else 'desktop-web' end,
          case when g % 10 < 7 then '{"verificationTypesOnPath":["government-id"],"fallbacksTaken":[],"flags":[]}'::jsonb end,
          ${day}, ${day}
        from inquiries s cross join generate_series(${from}::int, ${to}::int) g
        where s.id = ${tenant.seed_id}`);
      await tx.execute(sql`insert into verifications (id, environment_id, inquiry_id, type, status,
          country, created_at, updated_at)
        select ${id('ver')}, i.environment_id, i.id,
          (case when g % 2 = 0 then 'government_id' else 'selfie' end)::verification_type,
          (case when g % 9 = 0 then 'failed' else 'passed' end)::verification_status,
          case when g % 2 = 0 then 'FR' end, i.created_at, i.updated_at
        from generate_series(${from * 2 - 1}::int, ${to * 2}::int) g
        join inquiries i on i.id = 'inq_' || upper(lpad(to_hex((g + 1) / 2), 26, '0'))`);
      await tx.execute(sql`insert into verification_checks (environment_id, verification_id, name,
          status, type, requirement, reasons, created_at, updated_at)
        select v.environment_id, v.id, c.name,
          (case when abs(hashtext(v.id || c.name)) % 20 = 0 then 'failed'
            when abs(hashtext(v.id || c.name)) % 20 = 1 then 'not_applicable'
            else 'passed' end)::check_status,
          'fraud', 'required',
          case when abs(hashtext(v.id || c.name)) % 20 = 1 then '{execution_error}'::text[]
            else '{}' end,
          v.created_at, v.updated_at
        from verifications v
        cross join (values ('id_barcode_detection'), ('id_expiration_detection'),
          ('id_compare_repeat'), ('id_age_inconsistency_detection'), ('id_po_box_detection'),
          ('id_entity_detection')) c(name)
        where v.environment_id = ${tenant.environment_id}
          and v.id >= ${`ver_${(from * 2 - 1).toString(16).toUpperCase().padStart(26, '0')}`}
          and v.id <= ${`ver_${(to * 2).toString(16).toUpperCase().padStart(26, '0')}`}`);
      await tx.execute(sql`insert into inquiry_flow_steps (environment_id, inquiry_id, seq, step_id,
          step_type, entered_at, exited_at, exit_port)
        select i.environment_id, i.id, s.seq, s.step_id, s.step_type,
          i.created_at + s.seq * interval '1 second', i.created_at + s.seq * interval '1 second',
          'next'
        from generate_series(${from}::int, ${to}::int) g
        join inquiries i on i.id = 'inq_' || upper(lpad(to_hex(g), 26, '0'))
        cross join (values (1, 'start', 'consent'), (2, 'document', 'government_id'),
          (3, 'done', 'completion')) s(seq, step_id, step_type)`);
      await tx.execute(
        benchmarkCasesStatement({
          environmentId: tenant.environment_id,
          caseTemplateId: BENCHMARK_CASE_TEMPLATE,
          caseTemplateVersionId: BENCHMARK_CASE_TEMPLATE_VERSION,
          from,
          to,
          fieldsSealed,
        }),
      );
      await tx.execute(sql`insert into benchmark_batches values (${index})`);
    });
    done.add(index);
    report('seed-batch', batchStarted, { batch: index });
  }
  await db.execute(sql`analyze`);
  report('seed-complete', started, { batches: done.size });
}

const READS: readonly AnalyticsReport[] = [
  'inquiries',
  'funnel',
  'verifications',
  'checks',
  'cases',
  'signals',
];

async function measure(db: Database): Promise<void> {
  const tenant = await tenantOf(db);
  if (tenant === null) {
    throw new Error('run --seed first');
  }
  const environmentId = tenant.environment_id;
  const logger = { info: () => undefined, warn: () => undefined, error: () => undefined };
  // A clean start: every rollup row and the state removed, then the first pass builds them.
  for (const table of [
    'analytics_inquiry_daily',
    'analytics_inquiry_tag_daily',
    'analytics_step_daily',
    'analytics_transition_daily',
    'analytics_path_daily',
    'analytics_verification_daily',
    'analytics_verification_step_daily',
    'analytics_check_daily',
    'analytics_check_reason_daily',
    'analytics_case_daily',
    'analytics_case_assignee_daily',
    'analytics_signal_daily',
    'analytics_rollup_state',
  ]) {
    await db.execute(sql`truncate ${sql.identifier(table)}`);
  }
  let now = NOW;
  const clock = { now: () => now };
  let started = performance.now();
  const built = await runAnalyticsRollup({ db, clock, logger });
  report('build', started, { days: built.days, failed: built.failed });

  // 48 hours of inquiries, verifications, checks and cases touched, then the next 5-minute pass.
  now = new Date(NOW.getTime() + 5 * 60_000);
  await touchRefreshWindow(db, environmentId);
  started = performance.now();
  const refreshed = await runAnalyticsRollup({ db, clock, logger });
  report('refresh-5-minute', started, { days: refreshed.days });

  // The first pass after the zone's midnight: every open day's outcomes.
  now = new Date('2026-11-01T23:10:00Z');
  started = performance.now();
  const daily = await runAnalyticsRollup({ db, clock, logger });
  report('refresh-after-midnight', started, { days: daily.days });

  for (const [from, label] of [
    ['2026-10-03', '30 days'],
    ['2026-08-04', '90 days'],
    ['2025-09-28', '400 days'],
  ] as const) {
    for (const read of READS) {
      started = performance.now();
      await readAnalyticsAnswer(
        { db, clock },
        read,
        { 'filter[from]': from, 'filter[to]': '2026-11-01' },
        { environmentId, mayReadAssignees: true },
      );
      report(`read ${read}`, started, { window: label });
    }
  }
}

/** The command. */
export async function main(argv: readonly string[] = process.argv.slice(2)): Promise<void> {
  const phase = parseAnalyticsBenchmarkArgs(argv);
  if (phase === ANALYTICS_BENCHMARK_TEARDOWN) {
    docker('rm', '-f', CONTAINER);
    process.stdout.write(`${JSON.stringify({ step: 'teardown', container: CONTAINER })}\n`);
    return;
  }
  const { pool, db } = await connect();
  try {
    await (phase === '--seed' ? seed(db) : measure(db));
  } finally {
    await pool.end();
  }
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error: unknown) => {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
  });
}
